Step 4 — Build the modal content on click, from the data:

const teamCards = document.querySelectorAll('.team-card');
const teamModal = document.getElementById('team-modal');
const modalTeamName = document.getElementById('modal-team-name');
const modalSquadList = document.getElementById('modal-squad-list');

const positionLabels = { GK: 'Goalkeepers', DF: 'Defenders', MF: 'Midfielders', FW: 'Forwards' };

teamCards.forEach((card) => {
    card.addEventListener('click', () => {
        const team = teams[card.dataset.team];
        modalTeamName.textContent = team.name;

        modalSquadList.innerHTML = '';
        for (const pos of ['GK', 'DF', 'MF', 'FW']) {
            const heading = document.createElement('h4');
            heading.textContent = positionLabels[pos];
            const list = document.createElement('p');
            list.textContent = team[pos].join(', ');
            modalSquadList.append(heading, list);
        }

        teamModal.classList.add('open');
    });
});

teamModal.querySelector('.modal-close').addEventListener('click', () => {
    teamModal.classList.remove('open');
});

teamModal.addEventListener('click', (event) => {
    if (event.target === teamModal) teamModal.classList.remove('open');
});

This replaces your old per-team open/close wiring — same behavior, one shared modal.

Your move: this pattern scales to as many teams as you want just by adding entries to the teams object — no new HTML or CSS needed per team. Do you want me to pull the remaining ~45 teams' rosters (I already have most of them from the search results, just missing a couple like Ghana and Panama I'd need to look up) and hand you the complete teams object, or do you want to scope this down to a smaller, more curated set of teams instead, given the assignment only requires the feature to exist, not full tournament coverage?

